CREATE OR REPLACE FUNCTION public.record_learning_attempt(p_answers jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; s integer; t integer; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF jsonb_typeof(p_answers)<>'array' OR jsonb_array_length(p_answers)<>10 THEN RAISE EXCEPTION 'Invalid answers'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_answers) a WHERE a <> 'null'::jsonb AND (jsonb_typeof(a)<>'number' OR a::text !~ '^[0-3]$')) THEN RAISE EXCEPTION 'Invalid option'; END IF; SELECT count(*),count(*) FILTER(WHERE (p_answers->>(position-1))::integer=answer) INTO t,s FROM (SELECT * FROM public.learning_questions WHERE published ORDER BY position LIMIT 10) q; SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); INSERT INTO public.learning_attempts(user_id,parcours,answers,correct,total) VALUES(auth.uid(),p,p_answers,s,t) RETURNING id INTO result; RETURN result; END $$;